def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    dangerous_prev = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev['bid']
                prev_bids.append(bid)
                if bid >= 100:
                    dangerous_prev.append(bid)

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    moderate_prev = [b for b in prev_bids if b < 100]
    highest_moderate = max(moderate_prev) if moderate_prev else 0.0

    supply_tight = supply <= 17
    supply_loose = supply >= 22

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if supply_tight:
        urgency += 1

    if day >= 8:
        urgency += 1

    if urgency >= 6:
        bid = 128.0 if dangerous_prev else max(72.0, highest_moderate + 6.0)
    elif urgency >= 4:
        if dangerous_prev:
            bid = 96.0
        else:
            bid = max(54.0, highest_moderate + 3.0)
    elif urgency >= 2:
        if supply_loose:
            bid = 24.0
        else:
            bid = 38.0 if highest_moderate < 35 else min(58.0, highest_moderate + 2.0)
    else:
        if supply_loose:
            bid = 12.0
        else:
            bid = 20.0 if highest_moderate < 25 else 28.0

    reserve = 0.0
    if day <= 7:
        reserve = DAILY_SALARY * (10 - day) * 0.18
    max_affordable = max(0.0, budget - reserve)
    if hp <= 2 or no_water_days >= 2:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Alive opponents and their yesterday bids
    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            prev = o.get('previous_trace', {}) or {}
            bid = prev.get('bid', None)
            if bid is None:
                continue
            alive.append((oid, float(bid), o))

    # Budget safety
    budget = float(my_status.get('budget', 0.0))
    hp = float(my_status.get('hp', 0.0))

    # If no info, bid a conservative amount
    if not alive:
        target = DAILY_SALARY * 0.55
        return min(budget, target)

    # Pressure from yesterday
    yesterday_bids = [b for _, b, _ in alive]
    highest_prev = max(yesterday_bids)
    second_prev = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else highest_prev

    # Compute a pressure factor: how aggressive others were
    # If highest_prev was near/above 0.85*DAILY_SALARY, assume strong competition.
    pressure = 0.0
    if highest_prev >= 0.85 * DAILY_SALARY:
        pressure = 1.0
    elif highest_prev >= 0.6 * DAILY_SALARY:
        pressure = 0.7
    elif highest_prev >= 0.35 * DAILY_SALARY:
        pressure = 0.4
    else:
        pressure = 0.2

    # Base bid depends on supply: higher supply means we can bid less to secure water.
    # Supply is between 15 and 25.
    supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if (MAX_SUPPLY - MIN_SUPPLY) != 0 else 0.5
    supply_norm = 0.0 if supply_norm < 0.0 else (1.0 if supply_norm > 1.0 else supply_norm)

    # Need more when hp is low
    if hp <= 2:
        hp_mult = 1.25
    elif hp <= 4:
        hp_mult = 1.1
    else:
        hp_mult = 0.95

    # Aim to slightly beat the second-highest yesterday bid when competition is high.
    # Otherwise, bid around a fraction of the salary.
    if pressure >= 0.7:
        target = second_prev + 3.0
    else:
        target = DAILY_SALARY * (0.45 + 0.25 * pressure)

    # Adjust for supply: with more supply, reduce bid; with less, increase.
    target = target * (0.95 + 0.1 * (1.0 - supply_norm))

    # Ensure we don't overspend: keep a reserve for later days.
    # Reserve more when hp is healthy.
    if hp >= 6:
        reserve_frac = 0.35
    else:
        reserve_frac = 0.15

    max_affordable = max(0.0, budget * (1.0 - reserve_frac))
    target = min(target, max_affordable)

    # If budget is tiny, bid whatever remains.
    if budget <= 1.0:
        return max(0.0, budget)

    # Final clamp
    if target < 0.0:
        target = 0.0
    return min(budget, target)
